import math

def smallest_bore(F_extend, F_retract, p, rod_ratio, bores):
    """Smallest bore (m) from the list `bores` whose cylinder can push F_extend (N) and pull
    F_retract (N) at pressure p (Pa). The rod diameter is rod_ratio times the bore.
    Returns None if no bore in the list is big enough."""
    for D in sorted(bores):
        A = math.pi * D**2 / 4
        if p * A >= F_extend and p * A >= F_retract:
            return D
    return None

